export class RpcError extends Error {
    code;
    method;
    constructor(message, code, name, method) {
        super(method ? `[${method}] ${message}` : message);
        this.name = name ?? 'RpcError';
        this.code = code;
        this.method = method;
    }
    static fromPayload(payload, method) {
        const error = new RpcError(payload.message, payload.code, payload.name, method);
        if (payload.stack) {
            error.stack = payload.stack;
        }
        return error;
    }
    toPayload() {
        return {
            message: this.message,
            code: this.code,
            name: this.name,
            stack: this.stack,
        };
    }
}
