import { RpcError, } from './types';
function newRequestId() {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
        return crypto.randomUUID();
    }
    return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
}
/**
 * Main-thread RPC client over a Worker (or any WorkerLike MessagePort pair).
 */
export function createWorkerClient(worker) {
    const pending = new Map();
    const streams = new Map();
    const listeners = new Map();
    const onMessage = (ev) => {
        const msg = ev.data;
        if (!msg || typeof msg !== 'object' || !('kind' in msg)) {
            return;
        }
        if (msg.kind === 'event') {
            const set = listeners.get(msg.event);
            if (!set)
                return;
            for (const handler of set) {
                try {
                    handler(msg.payload);
                }
                catch (err) {
                    console.error('[worker-rpc] event handler error', err);
                }
            }
            return;
        }
        if (msg.kind === 'stream') {
            streams.get(msg.id)?.push(msg.value);
            return;
        }
        if (msg.kind === 'stream-done') {
            const stream = streams.get(msg.id);
            if (stream) {
                streams.delete(msg.id);
                stream.end();
            }
            return;
        }
        if (msg.kind === 'result') {
            const stream = streams.get(msg.id);
            if (stream) {
                streams.delete(msg.id);
                // Narrow with `===` so TS discriminates the generic RpcResponse union.
                if (msg.ok === true) {
                    stream.push(msg.value);
                    stream.end();
                }
                else {
                    stream.fail(RpcError.fromPayload(msg.error, String(msg.method)));
                }
                return;
            }
            const slot = pending.get(msg.id);
            if (!slot)
                return;
            pending.delete(msg.id);
            if (msg.ok === true) {
                slot.resolve(msg.value);
            }
            else {
                slot.reject(RpcError.fromPayload(msg.error, String(msg.method)));
            }
        }
    };
    worker.addEventListener('message', onMessage);
    function postCall(method, args, options, stream) {
        const id = newRequestId();
        const message = {
            kind: 'call',
            id,
            method,
            args,
            stream: stream || undefined,
        };
        worker.postMessage(message, options?.transfer);
        return id;
    }
    return {
        worker,
        call(method, args, options) {
            const id = postCall(method, args, options, false);
            const { promise, resolve, reject } = Promise.withResolvers();
            pending.set(id, {
                resolve: resolve,
                reject,
            });
            return promise;
        },
        async *stream(method, args, options) {
            const id = postCall(method, args, options, true);
            const queue = [];
            let done = false;
            let error;
            let wake;
            const notify = () => {
                wake?.();
                wake = undefined;
            };
            streams.set(id, {
                push: (value) => {
                    queue.push(value);
                    notify();
                },
                end: () => {
                    done = true;
                    notify();
                },
                fail: (reason) => {
                    error = reason;
                    done = true;
                    notify();
                },
            });
            try {
                while (true) {
                    if (queue.length > 0) {
                        yield queue.shift();
                        continue;
                    }
                    if (error) {
                        throw error;
                    }
                    if (done) {
                        return;
                    }
                    await new Promise((resolve) => {
                        wake = resolve;
                    });
                }
            }
            finally {
                streams.delete(id);
            }
        },
        on(event, handler) {
            const set = listeners.get(event) ?? new Set();
            set.add(handler);
            listeners.set(event, set);
            return () => {
                set.delete(handler);
                if (set.size === 0) {
                    listeners.delete(event);
                }
            };
        },
        terminate() {
            worker.removeEventListener('message', onMessage);
            for (const [, slot] of pending) {
                slot.reject(new RpcError('Worker terminated', 'WORKER_TERMINATED'));
            }
            pending.clear();
            for (const [, stream] of streams) {
                stream.fail(new RpcError('Worker terminated', 'WORKER_TERMINATED'));
            }
            streams.clear();
            listeners.clear();
            if (typeof worker.terminate === 'function') {
                worker.terminate();
            }
            else {
                worker.close?.();
            }
        },
    };
}
